using System.Collections.Generic;

public static class UserRepository
{
    public sealed record Query(string Sql, Dictionary<string, object> Parameters);

    // BUG: interpolates the raw username straight into the SQL text - a
    // classic injection (a username of "' OR '1'='1" changes the query's
    // meaning entirely).
    public static Query BuildLookupQuery(string username)
    {
        var sql = $"SELECT * FROM Users WHERE Username = '{username}'";
        return new Query(sql, new Dictionary<string, object>());
    }
}

