using System;
using Xunit;

public class UserRepositoryTests
{
    [Fact]
    public void NormalUsernameProducesAParameterizedQuery()
    {
        var q = UserRepository.BuildLookupQuery("ada");
        Assert.Contains("@username", q.Sql);
        Assert.Equal("ada", q.Parameters["@username"]);
    }

    [Fact]
    public void HostilePayloadNeverAppearsInTheSqlText()
    {
        const string payload = "' OR '1'='1";
        var q = UserRepository.BuildLookupQuery(payload);

        // the raw payload must not be embedded in the SQL string itself -
        // it belongs in the parameter, not the query text
        Assert.DoesNotContain(payload, q.Sql);
        Assert.DoesNotContain("OR '1'='1", q.Sql);
    }

    [Fact]
    public void HostilePayloadArrivesIntactAsABoundParameter()
    {
        const string payload = "' OR '1'='1";
        var q = UserRepository.BuildLookupQuery(payload);

        Assert.True(q.Parameters.ContainsKey("@username"));
        Assert.Equal(payload, q.Parameters["@username"]);
    }

    [Fact]
    public void SqlTextIsStableAcrossDifferentInputValues()
    {
        // a parameterized query's TEXT does not change with the input value
        // (only the bound parameter does) - this is what lets a DB cache
        // and safely reuse the query plan, and it's what an interpolated
        // (even escaped) query can never guarantee
        var q1 = UserRepository.BuildLookupQuery("ada");
        var q2 = UserRepository.BuildLookupQuery("grace");
        Assert.Equal(q1.Sql, q2.Sql);
    }
}

