using System.Collections.Generic;

public static class UserRepository
{
    public sealed record Query(string Sql, Dictionary<string, object> Parameters);

    public static Query BuildLookupQuery(string username)
    {
        var escaped = username.Replace("'", "''");
        var sql = $"SELECT * FROM Users WHERE Username = '{escaped}'";
        return new Query(sql, new Dictionary<string, object>());
    }
}
